vismSplModemToneBitMap = MibScalar((1, 3, 6, 1, 4, 1, 351, 110, 3, 17, 4, 43), Bits().clone(namedValues=NamedValues(("vism1560980Tone", 0)))).setMaxAccess("readwrite")
