vismPvcAlarmLogAdminTimer = MibScalar((1, 3, 6, 1, 4, 1, 351, 110, 3, 17, 4, 47), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 2147483647)).clone(7200)).setUnits('minutes').setMaxAccess("readwrite")
