vismPvcAlarmLogOperTimer = MibScalar((1, 3, 6, 1, 4, 1, 351, 110, 3, 17, 4, 48), Unsigned32().subtype(subtypeSpec=ValueRangeConstraint(0, 2147483647))).setUnits('minutes').setMaxAccess("readonly")
